  external_exports.object({ method: external_exports.literal("cancelRequest"), requestId: external_exports.string().min(1) }).strict(),
  // close：关闭指定受控 tab（tabId 缺省=当前 tab）。manager 层处理：detach + 通知 renderer 卸载 webview。
  external_exports.object({ method: external_exports.literal("close"), tabId: external_exports.string().optional() }).strict(),
  // list：枚举当前会话窗口下所有受控 tab 摘要。manager 层拦截处理，返回 result.tabs。
  external_exports.object({ method: external_exports.literal("list") }).strict()
