// ../shared/src/diagnosticPrivacy.ts
var messages = new Set(diagnosticMessages);
var numericKeys = new Set(DiagnosticMetricSchema.options);
var modules = new Set(diagnosticModules);
var prefixes = [...diagnosticPrefixes].sort((a, b) => b.length - a.length);
function safeDiagnosticFrames(stack) {
  if (typeof stack !== "string") return [];
  const result = [];
  for (const line of stack.split("\n").slice(0, 32)) {
    const normalized = line.replaceAll("\\", "/");
    const match = /((?:apps\/zcode-cli\/|packages\/)[^\s():]+):(\d+):(\d+)/.exec(normalized);
    if (match && modules.has(match[1])) result.push(`${match[1]}:${match[2]}:${match[3]}`);
    else {
      const bundle = /(?:^|[/\\])((?:main|host|scheduler|preload)\/index\.js|zcode\.cjs):(\d+):(\d+)/.exec(
        normalized
      );
      if (bundle) result.push(`${bundle[1]}:${bundle[2]}:${bundle[3]}`);
      else {
        const renderer = /(?:assets\/[^\s/():]+\.js|renderer-bundle\.js):(\d+):(\d+)/.exec(
          normalized
        );
        if (renderer) result.push(`renderer-bundle.js:${renderer[1]}:${renderer[2]}`);
      }
    }
    if (result.length === 12) break;
  }
  return result;
}

